    """
    returns encoded string by shifting characters in the string by a certain amount.
    """
    return "".join([chr((ord(c) - 65 + shift) % 26 + 65) if 'A' <= c <= 'Z'
                    else chr((ord(c) - 97 + shift) % 26 + 97) if 'a' <= c <= 'z'
                    else c for c in s])


